//! Temporary pre-repair native probe; replaced by the regression gate after measurement.
use safe_cex_venue_hyperliquid::rate_limit::get_hyperliquid_rest_request_weight;
use serde_json::{Value,json};
#[test]
fn pre_repair_native_weight_probe(){
 let mut inputs=vec![];
 for raw in [r#"{"toString":0}"#,r#"{"valueOf":0,"toString":0}"#,r#"[{"toString":0}]"#,r#"{"toString":"x"}"#,r#"{}"#,r#"[60]"#]{inputs.push(("/info",json!({"type":"candleSnapshot","limit":serde_json::from_str::<Value>(raw).unwrap()})));}
 for kind in [Some(json!("unexpected")),None,Some(Value::Null)]{let mut action=json!({"":vec![Value::Null;40]});if let Some(kind)=kind{action["type"]=kind}inputs.push(("/exchange",json!({"action":action})));}
 inputs.push(("/exchange",json!({"action":{"type":"order","orders":vec![Value::Null;40]}})));
 inputs.push(("/info",Value::String(r#"{"type":"userRole","unused":"\ud800"}"#.into())));
 inputs.push(("/info",Value::String(format!("{{\"type\":\"userRole\",\"unused\":{}0{}}}","[".repeat(140),"]".repeat(140)))));
 inputs.push(("/info",Value::String(r#"{"type":"userRole","unused":"\ud83d\ude00"}"#.into())));
 inputs.push(("/info",Value::String(r#"{"type":"userRole","unused":"\\ud800"}"#.into())));
 let expected:[f64;14]=[20.,20.,20.,20.,20.,21.,2.,2.,2.,2.,20.,20.,60.,60.];
 assert_eq!(inputs.len(),14,"independent pre-repair probe floor");
 let mut measured=vec![];
 for(index,((url,data),expected))in inputs.iter().zip(expected).enumerate(){let actual=get_hyperliquid_rest_request_weight(url,data);assert_eq!(actual.to_bits(),expected.to_bits(),"pre-repair native weight at {index}");measured.push(actual);}
 assert_eq!(measured.len(),14,"actual pre-repair completed probe count");
 println!("PRE_REPAIR_NATIVE_WEIGHTS={measured:?}; stopped at index13");
}
